class Solution {
  public int fixedPoint(int[] arr) {
    // arr[i] - i is non-decreasing for distinct sorted integers: find the first i with arr[i] >= i
    int lo = 0, hi = arr.length - 1, ans = -1;
    while (lo <= hi) {
      int mid = (lo + hi) >>> 1;
      if (arr[mid] >= mid) {
        if (arr[mid] == mid) ans = mid;
        hi = mid - 1;
      } else lo = mid + 1;
    }
    return ans;
  }
}
